using System;
using UnityEngine;
using InControl;
using Game.Input;
using Framework.Input.Integrations.InControl;

namespace Game.Tests
{
    /// <summary>
    /// InControl入力アダプターの動作確認用クラス。
    ///
    /// 操作登録、入力制御、終了処理などの
    /// 基本機能を自動テストする。
    /// </summary>
    public class InControlInputAdapterTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("テスト設定")]

        /// <summary>
        /// 開始時に自動テストを実行するか。
        /// </summary>
        [SerializeField]
        [Tooltip("開始時に全自動テストを実行する")]
        private bool runTestsOnStart = true;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// テスト用のゲーム操作セット。
        /// </summary>
        private GameplayActions gameplayActions;

        /// <summary>
        /// テスト対象の入力アダプター。
        /// </summary>
        private InControlInputAdapter<GameInputAction>
            adapter;

        /// <summary>
        /// 成功したテスト項目数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト項目数。
        /// </summary>
        private int failedCount;

        #endregion

        #region Unity Methods

        /// <summary>
        /// シーン開始時の処理。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// コンポーネント破棄時の処理。
        /// </summary>
        private void OnDestroy()
        {
            ReleaseTestObjects();
        }

        #endregion

        #region Test Control Methods

        /// <summary>
        /// すべての自動テストを実行する。
        /// </summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                TestInitialization();
                TestRegistration();
                TestDuplicateRegistration();
                TestActionLookup();
                TestInputAccess();
                TestInputControl();
                TestUnregistration();
                TestClearActions();
                TestInvalidArguments();
                TestDispose();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                ReleaseTestObjects();
                PrintTestResult();
            }
        }

        /// <summary>
        /// テスト用の操作セットとAdapterを再生成する。
        /// </summary>
        private void CreateTestObjects()
        {
            ReleaseTestObjects();

            // 物理入力に影響されないように、
            // 初期キー割り当てなしで生成する。
            gameplayActions = new GameplayActions();

            adapter =
                new InControlInputAdapter<GameInputAction>();
        }

        /// <summary>
        /// テスト用オブジェクトを解放する。
        /// </summary>
        private void ReleaseTestObjects()
        {
            if (adapter != null)
            {
                adapter.Dispose();
                adapter = null;
            }

            if (gameplayActions != null)
            {
                gameplayActions.Destroy();
                gameplayActions = null;
            }
        }

        /// <summary>
        /// テストに使用する基本操作を登録する。
        /// </summary>
        private void RegisterTestActions()
        {
            adapter.RegisterAction(
                GameInputAction.MoveUp,
                gameplayActions.MoveUp);

            adapter.RegisterAction(
                GameInputAction.UseItem,
                gameplayActions.UseItem);

            adapter.RegisterTwoAxisAction(
                GameInputAction.Move,
                gameplayActions.Move);
        }

        #endregion

        #region Test Methods

        /// <summary>
        /// 初期化処理を検証する。
        /// </summary>
        private void TestInitialization()
        {
            CreateTestObjects();

            Check(
                !adapter.IsInitialized,
                "初期化前の状態");

            Check(
                !adapter.IsInputEnabled,
                "初期化前の入力無効状態");

            Check(
                adapter.ActionCount == 0,
                "初期状態の操作数");

            adapter.Initialize();

            Check(
                adapter.IsInitialized,
                "初期化の完了");

            Check(
                adapter.IsInputEnabled,
                "初期化後の入力有効状態");

            adapter.SetInputEnabled(false);
            adapter.Initialize();

            Check(
                !adapter.IsInputEnabled,
                "重複初期化による状態変更の防止");

            CreateTestObjects();

            adapter.Initialize(false);

            Check(
                adapter.IsInitialized &&
                !adapter.IsInputEnabled,
                "入力無効状態での初期化");
        }

        /// <summary>
        /// 操作登録処理を検証する。
        /// </summary>
        private void TestRegistration()
        {
            CreateTestObjects();

            Check(
                adapter.RegisterAction(
                    GameInputAction.MoveUp,
                    gameplayActions.MoveUp),
                "個別操作の登録");

            Check(
                adapter.RegisterAction(
                    GameInputAction.UseItem,
                    gameplayActions.UseItem),
                "複数の個別操作の登録");

            Check(
                adapter.RegisterTwoAxisAction(
                    GameInputAction.Move,
                    gameplayActions.Move),
                "2軸操作の登録");

            Check(
                adapter.PlayerActionCount == 2,
                "個別操作数の確認");

            Check(
                adapter.TwoAxisActionCount == 1,
                "2軸操作数の確認");

            Check(
                adapter.ActionCount == 3,
                "全操作数の確認");

            adapter.Initialize();

            Check(
                adapter.ActionCount == 3,
                "初期化後の登録情報維持");
        }

        /// <summary>
        /// 操作の重複登録防止を検証する。
        /// </summary>
        private void TestDuplicateRegistration()
        {
            CreateTestObjects();
            RegisterTestActions();

            Check(
                !adapter.RegisterAction(
                    GameInputAction.MoveUp,
                    gameplayActions.MoveDown),
                "個別操作の重複登録拒否");

            Check(
                !adapter.RegisterTwoAxisAction(
                    GameInputAction.Move,
                    gameplayActions.Move),
                "2軸操作の重複登録拒否");

            Check(
                !adapter.RegisterAction(
                    GameInputAction.Move,
                    gameplayActions.MoveUp),
                "2軸操作IDへの個別操作登録拒否");

            Check(
                !adapter.RegisterTwoAxisAction(
                    GameInputAction.MoveUp,
                    gameplayActions.Move),
                "個別操作IDへの2軸操作登録拒否");

            Check(
                adapter.ActionCount == 3,
                "重複登録後の操作数維持");

            Check(
                adapter.TryGetPlayerAction(
                    GameInputAction.MoveUp,
                    out PlayerAction action) &&
                ReferenceEquals(
                    action,
                    gameplayActions.MoveUp),
                "既存操作の上書き防止");
        }

        /// <summary>
        /// 操作の検索処理を検証する。
        /// </summary>
        private void TestActionLookup()
        {
            CreateTestObjects();
            RegisterTestActions();

            Check(
                adapter.HasAction(
                    GameInputAction.MoveUp),
                "個別操作の存在確認");

            Check(
                adapter.HasAction(
                    GameInputAction.Move),
                "2軸操作の存在確認");

            Check(
                !adapter.HasAction(
                    GameInputAction.None),
                "未登録操作の存在確認");

            Check(
                adapter.TryGetPlayerAction(
                    GameInputAction.UseItem,
                    out PlayerAction action) &&
                ReferenceEquals(
                    action,
                    gameplayActions.UseItem),
                "個別操作の参照取得");

            Check(
                adapter.TryGetTwoAxisAction(
                    GameInputAction.Move,
                    out PlayerTwoAxisAction axis) &&
                ReferenceEquals(
                    axis,
                    gameplayActions.Move),
                "2軸操作の参照取得");

            Check(
                !adapter.TryGetPlayerAction(
                    GameInputAction.Move,
                    out _),
                "2軸操作の個別操作取得拒否");

            Check(
                !adapter.TryGetTwoAxisAction(
                    GameInputAction.MoveUp,
                    out _),
                "個別操作の2軸操作取得拒否");
        }

        /// <summary>
        /// 入力取得処理の基本動作を検証する。
        /// </summary>
        private void TestInputAccess()
        {
            CreateTestObjects();
            RegisterTestActions();

            adapter.Initialize();

            // キー割り当てが存在しないため、
            // すべての物理入力は無入力状態となる。
            Check(
                !adapter.GetButton(
                    GameInputAction.UseItem),
                "無入力時のボタン状態");

            Check(
                !adapter.GetButtonDown(
                    GameInputAction.UseItem),
                "無入力時の押下イベント");

            Check(
                !adapter.GetButtonUp(
                    GameInputAction.UseItem),
                "無入力時の解放イベント");

            Check(
                adapter.GetAxis(
                    GameInputAction.MoveUp) == 0f,
                "無入力時の1軸入力値");

            Check(
                adapter.GetVector2(
                    GameInputAction.Move) ==
                    Vector2.zero,
                "無入力時の2軸入力値");

            Check(
                !adapter.GetButton(
                    GameInputAction.None),
                "未登録ボタンの取得");

            Check(
                !adapter.GetButtonDown(
                    GameInputAction.None),
                "未登録ボタンの押下取得");

            Check(
                !adapter.GetButtonUp(
                    GameInputAction.None),
                "未登録ボタンの解放取得");

            Check(
                adapter.GetAxis(
                    GameInputAction.None) == 0f,
                "未登録1軸入力の取得");

            Check(
                adapter.GetVector2(
                    GameInputAction.None) ==
                    Vector2.zero,
                "未登録2軸入力の取得");

            Check(
                adapter.GetAxis(
                    GameInputAction.Move) == 0f,
                "2軸操作の1軸取得拒否");

            Check(
                adapter.GetVector2(
                    GameInputAction.MoveUp) ==
                    Vector2.zero,
                "個別操作の2軸取得拒否");
        }

        /// <summary>
        /// 入力の有効・無効切り替えを検証する。
        /// </summary>
        private void TestInputControl()
        {
            CreateTestObjects();
            RegisterTestActions();

            adapter.Initialize();
            adapter.SetInputEnabled(false);

            Check(
                !adapter.IsInputEnabled,
                "入力の無効化");

            Check(
                !adapter.GetButton(
                    GameInputAction.UseItem),
                "無効時のボタン取得");

            Check(
                !adapter.GetButtonDown(
                    GameInputAction.UseItem),
                "無効時の押下取得");

            Check(
                !adapter.GetButtonUp(
                    GameInputAction.UseItem),
                "無効時の解放取得");

            Check(
                adapter.GetAxis(
                    GameInputAction.MoveUp) == 0f,
                "無効時の1軸取得");

            Check(
                adapter.GetVector2(
                    GameInputAction.Move) ==
                    Vector2.zero,
                "無効時の2軸取得");

            Check(
                adapter.ActionCount == 3,
                "無効時の登録情報維持");

            Check(
                adapter.HasAction(
                    GameInputAction.UseItem),
                "無効時の操作存在確認");

            Check(
                adapter.TryGetPlayerAction(
                    GameInputAction.UseItem,
                    out _),
                "無効時の操作参照取得");

            adapter.SetInputEnabled(true);

            Check(
                adapter.IsInputEnabled,
                "入力の再有効化");
        }

        /// <summary>
        /// 個別の登録解除処理を検証する。
        /// </summary>
        private void TestUnregistration()
        {
            CreateTestObjects();
            RegisterTestActions();

            Check(
                adapter.UnregisterAction(
                    GameInputAction.MoveUp),
                "個別操作の登録解除");

            Check(
                !adapter.HasAction(
                    GameInputAction.MoveUp),
                "解除後の操作存在確認");

            Check(
                adapter.UnregisterAction(
                    GameInputAction.Move),
                "2軸操作の登録解除");

            Check(
                !adapter.UnregisterAction(
                    GameInputAction.None),
                "未登録操作の解除拒否");

            Check(
                adapter.ActionCount == 1,
                "登録解除後の操作数");

            Check(
                adapter.RegisterAction(
                    GameInputAction.MoveUp,
                    gameplayActions.MoveUp),
                "解除済み操作の再登録");
        }

        /// <summary>
        /// 全操作の登録解除を検証する。
        /// </summary>
        private void TestClearActions()
        {
            CreateTestObjects();
            RegisterTestActions();

            adapter.Initialize();
            adapter.ClearActions();

            Check(
                adapter.ActionCount == 0,
                "全操作の登録解除");

            Check(
                adapter.IsInitialized,
                "全解除後の初期化状態維持");

            Check(
                adapter.IsInputEnabled,
                "全解除後の入力状態維持");

            Check(
                adapter.RegisterAction(
                    GameInputAction.UseItem,
                    gameplayActions.UseItem),
                "全解除後の再登録");
        }

        /// <summary>
        /// 不正な引数の検証を行う。
        /// </summary>
        private void TestInvalidArguments()
        {
            CreateTestObjects();

            CheckThrows<ArgumentNullException>(
                () => adapter.RegisterAction(
                    GameInputAction.UseItem,
                    null),
                "null個別操作の登録拒否");

            CheckThrows<ArgumentNullException>(
                () => adapter.RegisterTwoAxisAction(
                    GameInputAction.Move,
                    null),
                "null 2軸操作の登録拒否");
        }

        /// <summary>
        /// 終了処理を検証する。
        /// </summary>
        private void TestDispose()
        {
            CreateTestObjects();
            RegisterTestActions();

            adapter.Initialize();
            adapter.Dispose();

            Check(
                !adapter.IsInitialized,
                "終了後の初期化状態");

            Check(
                !adapter.IsInputEnabled,
                "終了後の入力状態");

            Check(
                adapter.ActionCount == 0,
                "終了後の登録情報解除");

            Check(
                !adapter.HasAction(
                    GameInputAction.Move),
                "終了後の操作存在確認");

            Check(
                !adapter.GetButton(
                    GameInputAction.UseItem),
                "終了後のボタン取得");

            Check(
                adapter.GetAxis(
                    GameInputAction.MoveUp) == 0f,
                "終了後の1軸取得");

            Check(
                adapter.GetVector2(
                    GameInputAction.Move) ==
                    Vector2.zero,
                "終了後の2軸取得");

            CheckThrows<ObjectDisposedException>(
                () => adapter.Initialize(),
                "終了後の再初期化拒否");

            CheckThrows<ObjectDisposedException>(
                () => adapter.RegisterAction(
                    GameInputAction.UseItem,
                    gameplayActions.UseItem),
                "終了後の操作登録拒否");

            CheckThrows<ObjectDisposedException>(
                () => adapter.SetInputEnabled(true),
                "終了後の入力有効化拒否");

            // 終了処理を複数回呼び出しても安全か確認する。
            adapter.Dispose();

            Check(
                !adapter.IsInitialized &&
                adapter.ActionCount == 0,
                "終了処理の重複実行");

            // 元の操作セットを別のAdapterへ登録し、
            // Adapterが操作セットを所有しないことを確認する。
            using (var anotherAdapter =
                new InControlInputAdapter<GameInputAction>())
            {
                Check(
                    anotherAdapter.RegisterAction(
                        GameInputAction.UseItem,
                        gameplayActions.UseItem),
                    "終了後の操作参照再利用");
            }
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 指定された例外が発生するか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">実行する処理</param>
        /// <param name="testName">テスト項目名</param>
        private void CheckThrows<TException>(
            Action action,
            string testName)
            where TException : Exception
        {
            try
            {
                action();

                Check(false, testName);
            }
            catch (TException)
            {
                Check(true, testName);
            }
            catch (Exception exception)
            {
                Check(
                    false,
                    testName + "：" +
                    exception.GetType().Name);
            }
        }

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>
        /// テストの集計結果を出力する。
        /// </summary>
        private void PrintTestResult()
        {
            string message =
                "【InControlInputAdapter テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion
    }
}
